package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's shares, in the order added: another person on the sheet holding a part of the claim's due, as a
 *  percent with two decimals. */
@Repository
public class ClaimShareRepository {

    /** A share of a claim: the person holding it and their percent (two decimals). */
    public record Share(long personId, String share) {
        public BigDecimal pct() {
            return new BigDecimal(share);
        }
    }

    private final JdbcTemplate jdbc;

    public ClaimShareRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Keep a share of the claim, added on the day given (null: the sheet had no today). */
    public void add(Claim claim, long personId, BigDecimal share, LocalDate on) {
        jdbc.update("INSERT INTO claim_share (sheet_id, claim_id, person_id, share, on_date) VALUES (?, ?, ?, ?, ?)",
                claim.sheetId(), claim.id(), personId, share, on);
    }

    /** The claim's shares, in the order added. */
    public List<Share> of(Claim claim) {
        return jdbc.query("SELECT person_id, share FROM claim_share WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                (rs, i) -> new Share(rs.getLong("person_id"), rs.getBigDecimal("share").setScale(2).toPlainString()),
                claim.sheetId(), claim.id());
    }

    /** The shares of every claim on the sheet, by claim id, in the order added. */
    public Map<Long, List<Share>> shares(String sheetId) {
        return shares(sheetId, null);
    }

    /** The shares of every claim on the sheet as they stood at the end of the day (null: now), by claim id, in the
     *  order added: those added while the sheet's today was on or before it (or while it had none). */
    public Map<Long, List<Share>> shares(String sheetId, LocalDate end) {
        Map<Long, List<Share>> shares = new HashMap<>();
        jdbc.query("SELECT * FROM claim_share WHERE sheet_id = ? ORDER BY id", rs -> {
            LocalDate on = rs.getObject("on_date", LocalDate.class);
            if (end != null && on != null && on.isAfter(end)) {
                return;
            }
            shares.computeIfAbsent(rs.getLong("claim_id"), k -> new ArrayList<>())
                    .add(new Share(rs.getLong("person_id"), rs.getBigDecimal("share").setScale(2).toPlainString()));
        }, sheetId);
        return shares;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Share the loaded claim with another person on the sheet: not a SETTLED, VOID or DELETED claim, not with the
 *  claim's own person or a person already holding a share of it, and not so that its shares add up to more than
 *  100.00. */
public class SaveShare {
    public void save(@Val ShareInput input, @Val Claim loaded, PersonRepository people, ClaimShareRepository shares,
            SheetRepository sheets, Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException, PersonNotFoundException {
        if (loaded.status() == ClaimStatus.SETTLED || loaded.status() == ClaimStatus.VOID
                || loaded.status() == ClaimStatus.DELETED) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status() + " claim cannot be shared.");
        }
        Person with = people.find(loaded.sheetId(), input.personId());
        if (with == null) {
            throw new PersonNotFoundException(String.valueOf(input.personId()));
        }
        if (with.id() == loaded.personId()) {
            throw new ClaimStatusNotAllowedException("The claim is " + with.name() + "'s own; share it with someone else.");
        }
        List<ClaimShareRepository.Share> held = shares.of(loaded);
        if (held.stream().anyMatch(s -> s.personId() == with.id())) {
            throw new ClaimStatusNotAllowedException(with.name() + " already holds a share of this claim.");
        }
        BigDecimal total = held.stream().map(ClaimShareRepository.Share::pct).reduce(input.share(), BigDecimal::add);
        if (total.compareTo(new BigDecimal("100.00")) > 0) {
            throw new ClaimStatusNotAllowedException("The claim's shares would add up to " + total.toPlainString()
                    + ", more than 100.00.");
        }
        shares.add(loaded, with.id(), input.share(), sheets.today(loaded.sheetId()));
        saved.set(ClaimResponse.from(loaded, List.of(), sheets.today(loaded.sheetId())).withShares(shares.of(loaded)));
    }
}
-- A claim's shares, in the order added (by id): another person on the sheet holding a part of the claim's due, as a
-- percent with two decimals (above 0.00; a claim's shares add up to at most 100.00, one per person, never the claim's
-- own person). on_date is the sheet's today when the share was added (NULL when the sheet had none).
CREATE TABLE claim_share (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet(id),
    claim_id  BIGINT        NOT NULL REFERENCES claim(id),
    person_id BIGINT        NOT NULL,
    share     DECIMAL(5, 2) NOT NULL,
    on_date   DATE
);
CREATE INDEX claim_share_sheet ON claim_share(sheet_id, claim_id, id);

